{
  "name": "CVD沉积工艺控制系统",
  "name_en": "CVD Process Control System",
  "manufacturer": "",
  "description": "用于化学气相沉积（CVD）实验的工艺控制设备/系统，通常包含反应腔体加热温控、工艺配方（步骤）执行，以及多路工艺气体的流量设定与监控（常见为质量流量控制器MFC）。可按配方启动/停止工艺，并记录或回放工艺设定与相关参数变化。",
  "description_en": "A process control system for Chemical Vapor Deposition (CVD) experiments, typically integrating reactor temperature setpoint control, recipe (step) execution, and multi-gas flow setpoint/monitoring (commonly via mass flow controllers, MFCs). It supports starting/stopping a recipe and managing process setpoints and parameter trends during deposition runs.",
  "actions": [
    {
      "action_name": "auto-return_ui_fields",
      "description": "获取当前工艺界面中的配方/设定点字段",
      "description_en": "Get the current recipe/setpoint fields from the control interface"
    },
    {
      "action_name": "auto-save_recipe",
      "description": "保存工艺配方到文件（包含元数据与气体列信息）",
      "description_en": "Save a process recipe to a file (including metadata and gas column information)"
    },
    {
      "action_name": "auto-open_recipe",
      "description": "从文件打开工艺配方并加载到控制界面",
      "description_en": "Open a process recipe from a file and load it into the control interface"
    },
    {
      "action_name": "auto-update_plot",
      "description": "更新工艺参数趋势图（如多路气体流量随时间变化）",
      "description_en": "Update process trend plots (e.g., multi-gas flow vs. time)"
    },
    {
      "action_name": "auto-start_recipe",
      "description": "启动配方运行并开始执行工艺步骤",
      "description_en": "Start running a recipe and begin executing process steps"
    },
    {
      "action_name": "auto-stop_recipe",
      "description": "停止当前配方运行",
      "description_en": "Stop the currently running recipe"
    },
    {
      "action_name": "auto-apply_setpoints",
      "description": "应用当前设定点（如温度与气体流量设定）到工艺控制",
      "description_en": "Apply current setpoints (e.g., temperature and gas flow setpoints) to process control"
    }
  ],
  "tag_hints": [
    "chemical vapor deposition (CVD)",
    "process recipe execution",
    "gas flow setpoints",
    "mass flow controller (MFC)",
    "reactor temperature setpoint",
    "thin film deposition",
    "process trend plotting"
  ]
}
